<?php $token = Autenticacion::tokenFormulario(); $pedido = $detalle['pedido']; ?>
<!doctype html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pedido <?= htmlspecialchars($pedido['codigo']) ?></title><link rel="stylesheet" href="<?= URL_BASE ?>/public/css/styles1.css"></head>
<body class="pagina-simple"><main class="caja-checkout"><a href="<?= URL_BASE ?>/pedido">← Volver a pedidos</a><p class="etiqueta">Pedido <?= htmlspecialchars($pedido['codigo']) ?></p><h1><?= htmlspecialchars($pedido['cliente']) ?></h1><p><?= htmlspecialchars($pedido['correo']) ?> · <?= htmlspecialchars($pedido['creado_en']) ?></p>
<!-- Productos que formaron parte de la compra. -->
<div class="tabla-responsive"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($detalle['productos'] as $producto): ?><tr><td><?= htmlspecialchars($producto['nombre']) ?></td><td><?= (int)$producto['cantidad'] ?></td><td>S/ <?= number_format((float)$producto['precio_unitario'], 2) ?></td><td>S/ <?= number_format((float)$producto['subtotal'], 2) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="total-pedido">Total: S/ <?= number_format((float)$pedido['total'], 2) ?></p>
<!-- Al cancelar se devuelve stock; si se reactiva, el sistema comprueba stock nuevamente. -->
<form action="<?= URL_BASE ?>/pedido/estado/<?= (int)$pedido['id'] ?>" method="post"><input type="hidden" name="token" value="<?= htmlspecialchars($token) ?>"><label>Estado del pedido<select name="estado"><option value="pendiente" <?= $pedido['estado'] === 'pendiente' ? 'selected' : '' ?>>Pendiente</option><option value="pagado" <?= $pedido['estado'] === 'pagado' ? 'selected' : '' ?>>Pagado</option><option value="cancelado" <?= $pedido['estado'] === 'cancelado' ? 'selected' : '' ?>>Cancelado</option></select></label><button class="boton-principal">Actualizar estado</button></form></main></body></html>
